/* @autogenerated */
package net.civeira.phylax.features.oauth.tokensecurity.application.usecase;

import java.time.Instant;
import java.util.List;
import java.util.Map;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenRevocationGateway;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenSigner;

/**
 * Application use case for RFC 7009 token revocation.
 *
 * Responsibilities: - Parse and verify the submitted JWT. - Extract JTI and expiry for revocation
 * storage. - Delegate to {@link TokenRevocationGateway} to persist the revocation.
 *
 * Design notes: - All exceptions are swallowed; RFC 7009 §2.2 requires HTTP 200 even for invalid
 * tokens. - Token type is inferred from the hint or the scope claim when no hint is provided.
 */
@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class RevokeTokenUseCase {

  private final TokenSigner tokenSigner;
  private final TokenRevocationGateway revocationGateway;

  /**
   * Revokes a token by JTI if it is a valid, parseable JWT.
   *
   * Invalid or unparseable tokens are silently ignored (RFC 7009 §2.2). Expiry-less tokens cannot
   * be stored and are skipped.
   *
   * @param tenant tenant identifier
   * @param rawToken raw token string from the revocation request
   * @param tokenTypeHint optional hint from the client ({@code access_token} or
   *        {@code refresh_token})
   */
  public void revoke(String tenant, String rawToken, String tokenTypeHint) {
    if (rawToken == null || rawToken.isBlank()) {
      return;
    }
    try {
      Map<String, Object> payload = tokenSigner.verifyTokenPayload(tenant, rawToken);
      if (payload.isEmpty()) {
        return;
      }

      Object jtiObj = payload.get("jti");
      if (jtiObj == null) {
        return;
      }
      String jti = String.valueOf(jtiObj);

      Object exp = payload.get("exp");
      if (!(exp instanceof Number n)) {
        return;
      }
      Instant expiresAt = Instant.ofEpochSecond(n.longValue());

      String tokenType = resolveTokenType(payload, tokenTypeHint);
      revocationGateway.revokeJti(jti, tenant, tokenType, expiresAt);

    } catch (Exception e) {
      log.debug("Token revocation parse failed for tenant {} — treating as already invalid",
          tenant);
    }
  }

  private String resolveTokenType(Map<String, Object> payload, String hint) {
    if ("refresh_token".equals(hint) || "access_token".equals(hint)) {
      return hint;
    }
    Object scopeObj = payload.get("scope");
    if (scopeObj instanceof List<?> list && list.contains("refresh")) {
      return "refresh_token";
    }
    if (scopeObj instanceof String s && s.contains("refresh")) {
      return "refresh_token";
    }
    return "access_token";
  }
}
